import{_ as n,o as a,c as p,S as l}from"./chunks/framework.D1Ss-Xl7.js";const u=JSON.parse('{"title":"计算机中的字节序问题","description":"","frontmatter":{"title":"计算机中的字节序问题","date":"2014-09-30 12:30","comments":true,"archives":2014,"tags":["endian"]},"headers":[],"relativePath":"posts/2014-09-30-computer-endian/index.md","filePath":"posts/2014/2014-09-30-computer-endian.md"}'),e={name:"posts/2014-09-30-computer-endian/index.md"};function o(r,s,t,c,i,y){return a(),p("div",null,[...s[0]||(s[0]=[l(`<p>计算机字节序这个问题,最近被老师反复提到.我也在本科阶段折腾交叉编译的时候遇到过.并且这个问题貌似也是面试的时候一个常见问题,所以还是写下来比较好.</p><p>字节序顾名思义就是计算机中字节的存储顺序.目前最常见的就是大端字节序和小端字节序.貌似百科里面又有一个中端字节序...(不过确实很少见)</p><h2 id="大端字节序" tabindex="-1">大端字节序 <a class="header-anchor" href="#大端字节序" aria-label="Permalink to &quot;大端字节序&quot;">​</a></h2><p>按照最高位字节(包含最高位,即 MSB,的字节)至最低位字节(包含最低位,即 LSB,的字节)的顺序,存放在连续的地址中.</p><p>采用这种机制的处理器有 IBM3700 系列,和绝大多数的 RISC 处理(我的路由器就是)</p><h2 id="小端字节序" tabindex="-1">小端字节序 <a class="header-anchor" href="#小端字节序" aria-label="Permalink to &quot;小端字节序&quot;">​</a></h2><p>按照最低位字节(包含 LSB 的字节)至最高位字节(包含 MSB 的字节)的顺序,存放在连续的地址中.</p><p>采用这种机制的处理器最常见的就是 Intel 系列处理器</p><h2 id="判断字节序" tabindex="-1">判断字节序 <a class="header-anchor" href="#判断字节序" aria-label="Permalink to &quot;判断字节序&quot;">​</a></h2><p>当然字节序不能完全靠处理器来判断,因为有些处理器可能既支持大端字节序又支持小端字节序 最好用的方式还是用个程序跑一跑,实践是检验整理的唯一标准.</p><div class="language-cpp line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">#include</span><span style="color:#032F62;"> &lt;stdio.h&gt;</span></span>
<span class="line"><span style="color:#D73A49;">int</span><span style="color:#6F42C1;"> main</span><span style="color:#24292E;">()</span></span>
<span class="line"><span style="color:#24292E;">{</span></span>
<span class="line"><span style="color:#D73A49;">    unsigned</span><span style="color:#D73A49;"> int</span><span style="color:#24292E;"> x </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> 0x</span><span style="color:#005CC5;">12345678</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#D73A49;">    char</span><span style="color:#D73A49;"> *</span><span style="color:#24292E;">p </span><span style="color:#D73A49;">=</span><span style="color:#24292E;"> (</span><span style="color:#D73A49;">char</span><span style="color:#D73A49;"> *</span><span style="color:#24292E;">)</span><span style="color:#D73A49;">&amp;</span><span style="color:#24292E;">x;</span></span>
<span class="line"><span style="color:#D73A49;">    int</span><span style="color:#24292E;"> i;</span></span>
<span class="line"><span style="color:#D73A49;">    for</span><span style="color:#24292E;"> (i </span><span style="color:#D73A49;">=</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">; i </span><span style="color:#D73A49;">&lt;</span><span style="color:#D73A49;"> sizeof</span><span style="color:#24292E;">(x); i</span><span style="color:#D73A49;">++</span><span style="color:#24292E;">){</span></span>
<span class="line"><span style="color:#6F42C1;">        printf</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;</span><span style="color:#005CC5;">%.2x</span><span style="color:#032F62;"> &quot;</span><span style="color:#24292E;">, </span><span style="color:#D73A49;">*</span><span style="color:#24292E;">p</span><span style="color:#D73A49;">++</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#24292E;">    }</span></span>
<span class="line"><span style="color:#6F42C1;">    printf</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;</span><span style="color:#005CC5;">\\n</span><span style="color:#032F62;">&quot;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#D73A49;">    return</span><span style="color:#005CC5;"> 0</span><span style="color:#24292E;">;</span></span>
<span class="line"><span style="color:#24292E;">}</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br></div></div><p>上面的一段 C 程序就可以检验字节序,<br> 如果输出是：12 34 56 78,那么 CPU 是大端字节序.<br> 如果输出时：78 56 34 12,那么 CPU 是小端字节序.<br> 输出证明,大端字节序更适合人类阅读.</p><h2 id="涉及字节序的问题" tabindex="-1">涉及字节序的问题 <a class="header-anchor" href="#涉及字节序的问题" aria-label="Permalink to &quot;涉及字节序的问题&quot;">​</a></h2><p>谈到字节序问题,是因为网络编程的时候如果双方的字节序不一样肯定会出问题的.本人在交叉编译学校的校园网程序的时候就是遇到了这个问题,因为字节序的不同,导致发送的数据包是相反的.后来在老师的点拨下才得以解决.</p>`,14)])])}const b=n(e,[["render",o]]);export{u as __pageData,b as default};
